(()=>{const K="mipasantia_maqueta_v1",m={1:"assets/img/experiencias/logistica.png",2:"assets/img/experiencias/diseno.png",3:"assets/img/experiencias/tecnologia.png",4:"assets/img/experiencias/salud.png",5:"assets/img/experiencias/comunicacion.png"},sync=()=>{let d=JSON.parse(localStorage.getItem(K)||"{}");if(!Array.isArray(d.posts))return;let changed=false;d.posts.forEach(p=>{if(m[p.id]&&!p.foto){p.foto=m[p.id];changed=true}});if(changed)localStorage.setItem(K,JSON.stringify(d))};sync();new MutationObserver(sync).observe(document.body,{childList:true,subtree:true})})();
